127	function isStructuredObject(value: unknown): value is Record<string, unknown> {
128		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
129	}
130	
131	function toolInfoFromHostContext(value: unknown): {
132		id: string | number;
133		name: string;
134	} | null {
135		if (!isStructuredObject(value) || !isStructuredObject(value.toolInfo))
136			return null;
137		const id = value.toolInfo.id;
138		const tool = value.toolInfo.tool;
139		if (
140			(typeof id !== "string" && typeof id !== "number") ||
141			!isStructuredObject(tool) ||
142			typeof tool.name !== "string"
143		) {
144			return null;
145		}
146		return { id, name: tool.name };
147	}
