    17		const token = meta["lobu/mcp-app-snapshot-capability"];
    18		if (typeof token !== "string") return null;
    19		const normalized = token.trim();
    20		return normalized && normalized.length <= 512 ? normalized : null;
    21	}
    22	
    23	function isStructuredObject(value: unknown): value is UnknownRecord {
    24		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
    25	}
    26	
    27	export function approvalCapabilityFromMeta(meta: unknown): string | null {
    28		if (!isStructuredObject(meta)) return null;
    29		const token = meta["lobu/approval-capability"];
    30		return typeof token === "string" && token.length <= 4_096 ? token : null;
    31	}
    32	
    33	function approvalCapabilityFromResult(result: unknown): string | null {
    34		if (!isStructuredObject(result)) return null;
    35		return approvalCapabilityFromMeta(result._meta);
    36	}
    37	
    38	function snapshotCapabilityFromResult(
    39		result: unknown,
    40	): string | null | undefined {
    41		if (!isStructuredObject(result) || !Object.hasOwn(result, "_meta"))
    42			return undefined;
    43		return snapshotCapabilityFromMeta(result._meta);
    44	}
    45	
    46	/** Read the opaque per-result restore key from ChatGPT compatibility globals. */
    47	export function snapshotCapabilityFromOpenAiGlobals(
    48		globals: unknown,
    49	): string | null | undefined {
    50		if (!isStructuredObject(globals)) return undefined;
    51		const hasToolOutput = Object.hasOwn(globals, "toolOutput");
    52		const hasFullToolResult =
    53			hasToolOutput &&
    54			isStructuredObject(globals.toolOutput) &&
    55			Object.hasOwn(globals.toolOutput, "structuredContent");
    56		const hasToolResponseMetadata = Object.hasOwn(
    57			globals,
    58			"toolResponseMetadata",
    59		);
    60		const metadata = isStructuredObject(globals.toolResponseMetadata)
    61			? globals.toolResponseMetadata
    62			: null;
    63		if (hasToolResponseMetadata) {
    64			return metadata
    65				? (snapshotCapabilityFromResult(metadata.mcp_tool_result) ??
    66						snapshotCapabilityFromResult(metadata.call_tool_result) ??
    67						null)
    68				: null;
    69		}
    70		return hasFullToolResult
    71			? snapshotCapabilityFromResult(globals.toolOutput)
    72			: undefined;
    73	}
    74	
    75	function dataFromToolOutput<T>(toolOutput: unknown): T | null {
    76		if (!isStructuredObject(toolOutput)) return null;
    77		if (Object.hasOwn(toolOutput, "structuredContent")) {
    78			return isStructuredObject(toolOutput.structuredContent)
    79				? (toolOutput.structuredContent as T)
    80				: null;
    81		}
    82		return toolOutput as T;
    83	}
    84	
    85	function snapshotFromWidgetState<T>(widgetState: unknown): {
    86		data: T | null | undefined;
    87		resultIdentity: string | null | undefined;
    88	} {
    89		if (!isStructuredObject(widgetState)) {
    90			return { data: undefined, resultIdentity: undefined };
    91		}
    92		const privateContent = widgetState.privateContent;
    93		if (!isStructuredObject(privateContent)) {
    94			return { data: undefined, resultIdentity: undefined };
    95		}
    96		const snapshot = privateContent[LOBU_VIEW_SNAPSHOT_KEY];
    97		if (
    98			!isStructuredObject(snapshot) ||
    99			snapshot.version !== LOBU_VIEW_SNAPSHOT_VERSION
   100		) {
   101			return { data: undefined, resultIdentity: undefined };
   102		}
   103		const data =
   104			snapshot.data === null
   105				? null
   106				: isStructuredObject(snapshot.data)
   107					? (snapshot.data as T)
   108					: undefined;
   109		const resultIdentity = Object.hasOwn(snapshot, "resultIdentity")
   110			? typeof snapshot.resultIdentity === "string" &&
   111				snapshot.resultIdentity.trim() &&
   112				snapshot.resultIdentity.length <= 512
   113				? snapshot.resultIdentity
   114				: null
   115			: undefined;
   116		return { data, resultIdentity };
   117	}
   118	
   119	export function displaySafeOpenAiSnapshotData<T>(data: T | null): T | null {
   120		if (Array.isArray(data)) {
   121			return data.map((value) => displaySafeOpenAiSnapshotData(value)) as T;
   122		}
   123		if (!isStructuredObject(data)) return data;
   124		return Object.fromEntries(
   125			Object.entries(data).map(([key, value]) => {
   126				if (key === "actions" && Array.isArray(value)) {
   127					return [
   128						key,
   129						value
   130							.filter(
   131								(action) =>
   132									!isStructuredObject(action) ||
   133									action.tool !== "resolve_lobu_approval",
   134							)
   135							.map((action) => displaySafeOpenAiSnapshotData(action)),
   136					];
   137				}
   138				return [key, displaySafeOpenAiSnapshotData(value)];
   139			}),
   140		) as T;
   141	}
   142	
   143	/**
   144	 * Cache the latest server-authored view in ChatGPT's per-widget UI state. The
   145	 * snapshot is a display-only reload fallback; a fresh tool result always wins.
   146	 * Approval metadata stays excluded. The scoped snapshot capability is retained
   147	 * only as an opaque private correlation identity so delayed metadata cannot bind
   148	 * to another card merely because its display JSON happens to match.
   149	 */
   150	export function persistOpenAiViewSnapshot<T>(
   151		globals: unknown,
   152		data: T | null,
   153		resultIdentity: string | null = null,
   154	): boolean {
   155		if (!isStructuredObject(globals)) return false;
   156		const setWidgetState = globals.setWidgetState;
   157		if (typeof setWidgetState !== "function") return false;
   158	
   159		const widgetState = isStructuredObject(globals.widgetState)
   160			? globals.widgetState
   161			: {};
   162		const privateContent = isStructuredObject(widgetState.privateContent)
   163			? widgetState.privateContent
   164			: {};
   165		const nextWidgetState = {
   166			...widgetState,
   167			privateContent: {
   168				...privateContent,
   169				[LOBU_VIEW_SNAPSHOT_KEY]: {
   170					version: LOBU_VIEW_SNAPSHOT_VERSION,
   171					data: displaySafeOpenAiSnapshotData(data),
   172					...(resultIdentity ? { resultIdentity } : {}),
   173				},
   174			},
   175		};
   176	
   177		try {
   178			const result = Reflect.apply(setWidgetState, globals, [nextWidgetState]);
   179			if (isStructuredObject(result) && typeof result.catch === "function") {
   180				void Reflect.apply(result.catch, result, [() => {}]);
   181			}
   182			return true;
   183		} catch {
   184			return false;
   185		}
   186	}
   187	
   188	/**
   189	 * Read ChatGPT's compatibility globals without making them a dependency of the
   190	 * portable MCP Apps bridge. ChatGPT restores these globals for historical
   191	 * cards, including after the standard tool-result notification has already
   192	 * happened in an earlier page lifetime.
   193	 */
   194	export function readOpenAiCompatSnapshot<T>(
   195		globals: unknown,
   196	): OpenAiCompatSnapshot<T> {
   197		if (!isStructuredObject(globals)) {
   198			return {
   199				data: undefined,
   200				approvalCapability: undefined,
   201			};
   202		}
   203	
   204		const hasToolOutput = Object.hasOwn(globals, "toolOutput");
   205		const hasFullToolResult =
   206			hasToolOutput &&
   207			isStructuredObject(globals.toolOutput) &&
   208			Object.hasOwn(globals.toolOutput, "structuredContent");
   209		const widgetSnapshot = snapshotFromWidgetState<T>(globals.widgetState);
   210		const outputData = hasToolOutput
   211			? dataFromToolOutput<T>(globals.toolOutput)
   212			: widgetSnapshot.data;
   213		const hasToolResponseMetadata = Object.hasOwn(
   214			globals,
   215			"toolResponseMetadata",
   216		);
   217		const metadata = isStructuredObject(globals.toolResponseMetadata)
   218			? globals.toolResponseMetadata
   219			: null;
   220		const approvalCapability = hasToolResponseMetadata
   221			? metadata
   222				? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
   223					approvalCapabilityFromResult(metadata.call_tool_result))
   224				: null
   225			: hasFullToolResult
   226				? approvalCapabilityFromResult(globals.toolOutput)
   227				: undefined;
   228		const data =
   229			hasToolOutput && approvalCapability === null
   230				? displaySafeOpenAiSnapshotData(outputData)
   231				: outputData;
   232		const retainsWidgetIdentity =
   233			!hasToolOutput ||
   234			(isStructuredObject(outputData) && Object.keys(outputData).length === 0);
   235	
   236		return {
   237			data,
   238			...(retainsWidgetIdentity && widgetSnapshot.resultIdentity !== undefined
   239				? { resultIdentity: widgetSnapshot.resultIdentity }
   240				: {}),
   241			approvalCapability,
   242		};
   243	}

