it("keeps stale widget cache out of an in-flight capability boundary", async () => {
	const compatParent: CompatParent = Object.assign(new EventTarget(), {
		location: { origin: "https://chatgpt.com" },
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});
	type RestoreResult = {
		isError: false;
		structuredContent: {
			found: true;
			tool_name: string;
			data: { title: string };
			view_state: Record<string, never>;
		};
	};
	let resolveNextRestore!: (result: RestoreResult) => void;
	const nextRestore = new Promise<RestoreResult>((resolve) => {
		resolveNextRestore = resolve;
	});
	bridge.callServerTool.mockImplementation(
		async ({ name, arguments: args }) => {
			if (
				name === "restore_lobu_app_result" &&
				args.snapshot_capability === "old-widget-token"
			) {
				return {
					isError: false,
					structuredContent: {
						found: true,
						tool_name: "query_sdk",
						data: { title: "Old widget card" },
						view_state: {},
					},
				};
			}
			if (
				name === "restore_lobu_app_result" &&
				args.snapshot_capability === "new-widget-token"
			) {
				return nextRestore;
			}
			if (name === "save_lobu_app_state") {
				return { isError: false, structuredContent: { saved: true } };
			}
			return { isError: false };
		},
	);

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data } = useMcpApp<{ title: string }>();
		return <span>{data?.title ?? "No result"}</span>;
	}
	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));

	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({
				structuredContent: { title: "Old widget card" },
				_meta: {
					"lobu/mcp-app-snapshot-capability": "old-widget-token",
				},
			});
		}
	});
	expect(await screen.findByText("Old widget card")).toBeInTheDocument();

	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({
				structuredContent: {},
				_meta: {
					"lobu/mcp-app-snapshot-capability": "new-widget-token",
				},
			});
		}
	});
	await waitFor(() =>
		expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: { snapshot_capability: "new-widget-token" },
		}),
	);
	expect(await screen.findByText("No result")).toBeInTheDocument();

	act(() => {
		window.dispatchEvent(
			new CustomEvent("openai:set_globals", {
				detail: {
					globals: {
						widgetState: {
							privateContent: {
								lobuViewSnapshot: {
									version: 1,
									data: { title: "Old widget card" },
								},
							},
						},
					},
				},
			}),
		);
	});
	expect(screen.getByText("No result")).toBeInTheDocument();
	expect(screen.queryByText("Old widget card")).not.toBeInTheDocument();

	await act(async () => {
		resolveNextRestore({
			isError: false,
			structuredContent: {
				found: true,
				tool_name: "query_sdk",
				data: { title: "New widget card" },
				view_state: {},
			},
		});
		await nextRestore;
	});
	expect(await screen.findByText("New widget card")).toBeInTheDocument();
});

