		location: { origin: "https://portable-host.example" },
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});
	bridge.callServerTool.mockImplementation(async ({ name }) => ({
		isError: false,
		...(name === "restore_lobu_app_result"
			? {
					structuredContent: {
						found: true,
						tool_name: "stale_tool",
						data: { title: "Old compatibility card" },
						view_state: { "details.open": true },
					},
				}
			: {}),
	}));

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, toolName, viewState } = useMcpApp<{ title: string }>();
		return (
			<>
				<span>{data?.title ?? "No result"}</span>
				<span>tool:{toolName ?? "none"}</span>
				<span>open:{String(viewState["details.open"])}</span>
			</>
		);
	}
	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
	act(() => {
		window.dispatchEvent(
			new CustomEvent("openai:set_globals", {
				detail: {
					globals: { toolOutput: { title: "Old compatibility card" } },
				},
			}),
		);
	});
	expect(
		await screen.findByText("Old compatibility card"),
	).toBeInTheDocument();
	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({ structuredContent: { title: "Current standard card" } });
		}
	});
	expect(
		await screen.findByText("Current standard card"),
	).toBeInTheDocument();
	act(() => {
		window.dispatchEvent(
			new CustomEvent("openai:set_globals", {
				detail: {
					globals: {
						toolResponseMetadata: {
							mcp_tool_result: {
								_meta: {
									"lobu/mcp-app-snapshot-capability": "old-token",
								},
							},
						},
					},
				},
			}),
		);
	});
	await act(() => new Promise((resolve) => window.setTimeout(resolve, 0)));
	expect(bridge.callServerTool).not.toHaveBeenCalledWith({
		name: "restore_lobu_app_result",
		arguments: { snapshot_capability: "old-token" },
	});
	expect(screen.getByText("Current standard card")).toBeInTheDocument();
	expect(screen.getByText("tool:none")).toBeInTheDocument();
	expect(screen.getByText("open:undefined")).toBeInTheDocument();
});

