   379	
   380		return (
   381			<div className={container}>
   382				{view.title ? (
   383					<div className="mb-2 flex items-center gap-1.5 font-medium">
   384						{tone === "warning" ? (
   385							<ShieldAlert className="h-3.5 w-3.5 text-amber-600 dark:text-amber-500" />
   386						) : null}
   387						<span>{view.title}</span>
   388					</div>
   389				) : null}
   390				{blocks.length > 0 ? (
   391					<div className="mb-2 space-y-2">
   392						{blocks.map((b) => (
   393							<BlockView
   394								key={blockKey(b)}
   395								block={b}
   396								onAction={onAction}
   397								onFormValuesChange={setFormValues}
   398								disabled={pending}
   399							/>
   400						))}
   401					</div>
   402				) : null}
   403				{actions.length > 0 ? actionRow : null}
   404			</div>
   405		);
   406	};

